Mkdir::Mkdir(const int argc, char **argv) : HdfsTool(argc, argv) {}

bool Mkdir::Initialize() {
  auto add_options = opt_desc_.add_options();
  add_options("help,h",
              "Create the DIRECTORY(ies), if they do not already exist");
  add_options("parents,p", "Make parent directories as needed");
  add_options("mode,m", po::value<std::string>(),
              "Set file mode (octal permissions) for the new DIRECTORY(ies)");
  add_options("path", po::value<std::string>(),
              "The path to the directory to be created");

  // We allow only one positional argument to be passed to this tool. An
  // exception is thrown if multiple arguments are passed.
  pos_opt_desc_.add("path", 1);

  po::store(po::command_line_parser(argc_, argv_)
                .options(opt_desc_)
                .positional(pos_opt_desc_)
                .run(),
            opt_val_);
  po::notify(opt_val_);
  return true;
}

std::string Mkdir::GetDescription() const {
  std::stringstream desc;
  desc << "Usage: hdfs_mkdir [OPTION] DIRECTORY" << std::endl
       << std::endl
       << "Create the DIRECTORY(ies), if they do not already exist."
       << std::endl
       << std::endl
       << "  -p        make parent directories as needed" << std::endl
       << "  -m  MODE  set file mode (octal permissions) for the new "
          "DIRECTORY(ies)"
       << std::endl
       << "  -h        display this help and exit" << std::endl
       << std::endl
       << "Examples:" << std::endl
       << "hdfs_mkdir hdfs://localhost.localdomain:8020/dir1/dir2" << std::endl
       << "hdfs_mkdir -p /extant_dir/non_extant_dir/non_extant_dir/new_dir"
       << std::endl;
  return desc.str();
}

bool Mkdir::Do() {
  if (!Initialize()) {
    std::cerr << "Unable to initialize HDFS mkdir tool" << std::endl;
    return false;
  }

  if (!ValidateConstraints()) {
    std::cout << GetDescription();
    return false;
  }

  if (opt_val_.count("help") > 0) {
    return HandleHelp();
  }

  if (opt_val_.count("path") > 0) {
    const auto path = opt_val_["path"].as<std::string>();
    const auto create_parents = opt_val_.count("parents") > 0;
    const auto permissions =
        opt_val_.count("mode") > 0
            ? static_cast<uint16_t>(
                  std::stoul(opt_val_["mode"].as<std::string>(), nullptr, 8))
            : hdfs::FileSystem::GetDefaultPermissionMask();
    return HandlePath(path, create_parents, permissions);
  }

  return false;
}

