                       const uint16_t permissions) const {
  // Building a URI object from the given path
  auto uri = hdfs::parse_path_or_exit(path);

  const auto fs = hdfs::doConnect(uri, false);
  if (!fs) {
    std::cerr << "Could not connect the file system." << std::endl;
    return false;
  }

  const auto status = fs->Mkdirs(uri.get_path(), permissions, create_parents);
  if (!status.ok()) {
    std::cerr << "Error: " << status.ToString() << std::endl;
    return false;
  }
  return true;
